<div class="page-actions"><a class="back-link" href="<?= site_url('admin/modul/kdkmp') ?>">← Daftar KDKMP</a><span class="pill <?= $site['verification_status']==='verified'?'pill-green':'pill-muted' ?>"><?= $site['verification_status']==='verified'?'Progres terverifikasi':'Menunggu verval' ?></span><?php if ($can_archive): ?><form method="post" action="<?= site_url('admin/kdkmp/'.$site['id'].'/status') ?>" onsubmit="return confirm('Ubah status arsip lokasi ini?')"><?= csrf_input() ?><button class="button button-quiet" type="submit"><?= $site['archived_at']?'Aktifkan kembali':'Arsipkan lokasi' ?></button></form><?php endif; ?></div>
<?php if ($site['archived_at']): ?><div class="note-strip">Lokasi ini diarsipkan dan tidak masuk perhitungan aktif.</div><?php endif; ?>
<div class="profile-head"><div><span class="panel-overline"><?= h($site['district_name']) ?> / <?= h($site['village_name']) ?></span><h2><?= h($site['cooperative_name']) ?></h2><p>NIK <?= h($site['nik']) ?> · <?= h($site['location_name']?:'Lokasi fisik belum dinamai') ?></p></div><div class="assessment-progress"><strong><?= $site['physical_progress']===null?'—':h(number_format($site['physical_progress'],0,',','.').'%') ?></strong><small>progres fisik dilaporkan</small></div></div>
<div class="detail-grid"><section class="panel detail-panel"><span class="panel-overline">LOKASI</span><dl><dt>Alamat</dt><dd><?= h($site['address']?:$site['cooperative_address']?:'—') ?></dd><dt>Koordinat</dt><dd><?= $site['latitude']!==null?h($site['latitude'].', '.$site['longitude']):'Belum ada' ?></dd><dt>Operasional</dt><dd><?= h($site['operational_status']?:'Belum dilaporkan') ?></dd><dt>Verifikasi fisik</dt><dd><?= h($site['verification_status']) ?></dd></dl></section><section class="panel detail-panel"><span class="panel-overline">ATURAN CAPAIAN</span><p class="case-description">Progres yang diisi petugas belum menjadi capaian terbangun 100%. Capaian baru dihitung setelah progres 100, ada foto bukti yang disetujui, dan verifikator menekan tombol verifikasi.</p><?php if ($can_verify): ?><form method="post" action="<?= site_url('admin/kdkmp/'.$site['id'].'/verifikasi') ?>"><?= csrf_input() ?><button class="button button-dark" type="submit" <?= (float)$site['physical_progress']<100?'disabled':'' ?>>Verifikasi 100% →</button></form><?php endif; ?></section></div>
<?php if ($can_edit): ?><section class="form-panel case-followup"><div class="form-intro"><span class="panel-overline">PERKEMBANGAN LOKASI</span><h2>Perbarui kondisi lapangan</h2></div><form method="post" action="<?= site_url('admin/kdkmp/'.$site['id'].'/simpan') ?>"><?= csrf_input() ?><div class="form-grid"><label>Nama lokasi<input name="location_name" value="<?= h($site['location_name']) ?>"></label><label>Progres fisik (%)<input type="number" name="physical_progress" min="0" max="100" step="0.01" value="<?= h($site['physical_progress']) ?>"></label><label>Status operasional<select name="operational_status"><?php foreach (array('planned'=>'Direncanakan','building'=>'Dibangun','ready'=>'Siap beroperasi','operating'=>'Beroperasi') as $code=>$label): ?><option value="<?= $code ?>" <?= $site['operational_status']===$code?'selected':'' ?>><?= h($label) ?></option><?php endforeach; ?></select></label><label>Lintang<input type="number" name="latitude" min="-90" max="90" step="0.0000001" value="<?= h($site['latitude']) ?>"></label><label>Bujur<input type="number" name="longitude" min="-180" max="180" step="0.0000001" value="<?= h($site['longitude']) ?>"></label><label class="form-full">Alamat lokasi<textarea name="address" rows="2"><?= h($site['address']) ?></textarea></label><label class="form-full">Catatan sumber/perubahan <span class="required">*</span><textarea name="note" rows="3" required minlength="5" placeholder="Temuan lapangan dan sumber informasi"></textarea></label></div><div class="form-actions"><button class="button button-dark" type="submit">Simpan progres →</button></div></form></section><?php endif; ?>
<div class="detail-grid"><section class="panel detail-panel"><span class="panel-overline">FOTO BUKTI</span><?php foreach ($photos as $photo): ?><div class="evidence-row"><a class="row-link" href="<?= site_url('admin/kdkmp/'.$site['id'].'/foto/'.$photo['id']) ?>" target="_blank"><?= h($photo['original_name']) ?> ↗</a><span class="pill <?= $photo['verification_status']==='approved'?'pill-green':'pill-muted' ?>"><?= $photo['verification_status']==='approved'?'Disetujui':'Menunggu' ?></span><?php if ($can_verify && $photo['verification_status']!=='approved'): ?><form method="post" action="<?= site_url('admin/kdkmp/'.$site['id'].'/foto/'.$photo['id'].'/setujui') ?>"><?= csrf_input() ?><button class="text-button" type="submit">Setujui</button></form><?php endif; ?></div><?php endforeach; ?><?php if (!$photos): ?><p class="case-description">Belum ada foto bukti.</p><?php endif; ?><?php if ($can_edit): ?><form class="upload-inline" method="post" enctype="multipart/form-data" action="<?= site_url('admin/kdkmp/'.$site['id'].'/foto') ?>"><?= csrf_input() ?><label>Unggah foto JPG/PNG/WebP, maksimal 5 MB<input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required></label><button class="button button-dark button-small" type="submit">Simpan foto</button></form><?php endif; ?></section><section class="panel detail-panel"><span class="panel-overline">KOMODITAS</span><?php foreach ($commodities as $c): ?><div class="evidence-row"><strong><?= h($c['commodity_name']) ?></strong><span><?= h($c['capacity']?:'—') ?> <?= h($c['unit_name']) ?></span><small><?= h($c['report_period']) ?></small><?php if ($can_edit): ?><button class="text-button commodity-edit" type="button" data-id="<?= $c['id'] ?>" data-commodity="<?= $c['commodity_item_id'] ?>" data-unit="<?= $c['unit_item_id'] ?>" data-period="<?= h($c['report_period']) ?>" data-capacity="<?= h($c['capacity']) ?>" data-notes="<?= h($c['notes']) ?>">Ubah</button><?php endif; ?><?php if ($can_archive): ?><form method="post" action="<?= site_url('admin/kdkmp/'.$site['id'].'/komoditas/'.$c['id'].'/hapus') ?>" onsubmit="return confirm('Hapus laporan komoditas ini?')"><?= csrf_input() ?><button class="text-button" type="submit">Hapus</button></form><?php endif; ?></div><?php endforeach; ?><?php if (!$commodities): ?><p class="case-description">Belum ada komoditas yang dilaporkan.</p><?php endif; ?><?php if ($can_create || $can_edit): ?><form id="commodity-form" method="post" action="<?= site_url('admin/kdkmp/'.$site['id'].'/komoditas') ?>"><?= csrf_input() ?><input type="hidden" name="id" value=""><div class="form-grid"><label>Komoditas<select name="commodity_item_id" required><option value="">Pilih</option><?php foreach ($commodity_options as $x): ?><option value="<?= $x['id'] ?>"><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label>Satuan<select name="unit_item_id"><option value="">Pilih</option><?php foreach ($unit_options as $x): ?><option value="<?= $x['id'] ?>"><?= h($x['name']) ?></option><?php endforeach; ?></select></label><label>Periode<input type="date" name="report_period" required value="<?= date('Y-m-d') ?>"></label><label>Kapasitas<input type="number" name="capacity" min="0" step="0.001"></label><label class="form-full">Catatan<input name="notes"></label></div><div class="form-actions"><button class="button button-dark button-small" type="submit" <?= $can_create?'':'disabled' ?>>Simpan komoditas</button></div></form><?php if (!$commodity_options): ?><a class="text-link" href="<?= site_url('admin/master/komoditas') ?>">Isi master komoditas dahulu →</a><?php endif; ?><?php endif; ?></section></div>
<section class="panel detail-panel case-timeline"><span class="panel-overline">RIWAYAT PROGRES</span><?php foreach ($history as $e): ?><article class="timeline-item"><div class="timeline-dot"></div><strong><?= h($e['actor_name']) ?> <small><?= h(date('d M Y H:i',strtotime($e['created_at']))) ?></small></strong><p><?= h($e['progress']===null?'Tanpa angka progres':number_format($e['progress'],1,',','.').'%') ?> · <?= h($e['note']) ?></p></article><?php endforeach; ?><?php if (!$history): ?><p class="case-description">Belum ada riwayat progres.</p><?php endif; ?></section>
<script>(function(){const form=document.getElementById('commodity-form');if(!form)return;for(const button of document.querySelectorAll('.commodity-edit'))button.addEventListener('click',()=>{for(const [name,value] of Object.entries({id:button.dataset.id,commodity_item_id:button.dataset.commodity,unit_item_id:button.dataset.unit,report_period:button.dataset.period,capacity:button.dataset.capacity,notes:button.dataset.notes})){const field=form.elements.namedItem(name);if(field)field.value=value||'';}form.querySelector('button[type=submit]').disabled=false;form.scrollIntoView({behavior:'smooth',block:'center'});});})()</script>